import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  Param,
  Req,
  UseGuards,
} from '@nestjs/common';
import { DataSourceService } from './datasource.service';
import {
  CreateDataSourceDto,
  CreateDataSourceInWorkspaceDto,
  UpdateDataSourceDto,
  ExecuteQueryDto,
} from './datasource.dto';
import { JwtAuthGuard } from 'src/auth/jwt-auth.guard';
import { AuthenticatedRequest } from 'src/auth/auth.types';
import { WorkspaceService } from '../workspace/workspace.service';

@Controller()
@UseGuards(JwtAuthGuard)
export class DataSourceController {
  constructor(
    private readonly datasourceService: DataSourceService,
    private readonly workspaceService: WorkspaceService,
  ) {}

  // --- Workspace-scoped endpoints ---

  @Post('workspaces/:workspaceId/datasources')
  async createInWorkspace(
    @Param('workspaceId') workspaceIdOrSlug: string,
    @Req() req: AuthenticatedRequest,
    @Body() dto: CreateDataSourceDto,
  ) {
    const userId = Number(req.user.id);
    const workspaceId =
      await this.workspaceService.resolveId(workspaceIdOrSlug);
    await this.workspaceService.assertMember(workspaceId, userId);
    return this.datasourceService.create(userId, workspaceId, dto);
  }

  @Get('workspaces/:workspaceId/datasources')
  async findByWorkspace(
    @Param('workspaceId') workspaceIdOrSlug: string,
    @Req() req: AuthenticatedRequest,
  ) {
    const userId = Number(req.user.id);
    const workspaceId =
      await this.workspaceService.resolveId(workspaceIdOrSlug);
    await this.workspaceService.assertMember(workspaceId, userId);
    return this.datasourceService.findAllByWorkspace(workspaceId);
  }

  // --- Legacy / backward-compatible endpoints ---

  @Post('datasources')
  async create(
    @Req() req: AuthenticatedRequest,
    @Body() dto: CreateDataSourceInWorkspaceDto,
  ) {
    const userId = Number(req.user.id);
    await this.workspaceService.assertMember(dto.workspaceId, userId);
    return this.datasourceService.create(userId, dto.workspaceId, dto);
  }

  @Get('datasources')
  async findAll(@Req() req: AuthenticatedRequest) {
    const userId = Number(req.user.id);
    const workspaces = await this.workspaceService.findAllByUser(userId);
    const results = await Promise.all(
      workspaces.map((w) => this.datasourceService.findAllByWorkspace(w.id)),
    );
    return results.flat();
  }

  @Get('datasources/:id')
  async findOne(
    @Req() req: AuthenticatedRequest,
    @Param('id') id: string,
  ) {
    const ds = await this.datasourceService.findRaw(id);
    await this.workspaceService.assertMember(
      ds.workspaceId,
      Number(req.user.id),
    );
    return this.datasourceService.findOne(id);
  }

  @Patch('datasources/:id')
  async update(
    @Req() req: AuthenticatedRequest,
    @Param('id') id: string,
    @Body() dto: UpdateDataSourceDto,
  ) {
    const ds = await this.datasourceService.findRaw(id);
    await this.workspaceService.assertMember(
      ds.workspaceId,
      Number(req.user.id),
    );
    return this.datasourceService.update(id, dto);
  }

  @Delete('datasources/:id')
  async remove(
    @Req() req: AuthenticatedRequest,
    @Param('id') id: string,
  ) {
    const ds = await this.datasourceService.findRaw(id);
    await this.workspaceService.assertMember(
      ds.workspaceId,
      Number(req.user.id),
    );
    return this.datasourceService.remove(id);
  }

  @Post('datasources/:id/test')
  async testConnection(
    @Req() req: AuthenticatedRequest,
    @Param('id') id: string,
  ) {
    const ds = await this.datasourceService.findRaw(id);
    await this.workspaceService.assertMember(
      ds.workspaceId,
      Number(req.user.id),
    );
    return this.datasourceService.testConnection(id);
  }

  @Post('datasources/:id/query')
  async executeQuery(
    @Req() req: AuthenticatedRequest,
    @Param('id') id: string,
    @Body() dto: ExecuteQueryDto,
  ) {
    const ds = await this.datasourceService.findRaw(id);
    await this.workspaceService.assertMember(
      ds.workspaceId,
      Number(req.user.id),
    );
    return this.datasourceService.executeQuery(id, dto);
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { Client, types } from 'pg';
import { PrismaService } from 'src/database/prisma.service';
import { encrypt, decrypt } from './crypto.util';
import { validateSelectQuery } from './sql-validator';
import {
  CreateDataSourceDto,
  UpdateDataSourceDto,
  ExecuteQueryDto,
} from './datasource.dto';

const QUERY_TIMEOUT_MS = 30_000;
const MAX_ROWS = 10_000;

// Keep date/time types as raw Postgres text instead of JS `Date`, which the
// default parser shifts by the Node runtime timezone. (TIME/TIMETZ are strings.)
const RAW_TEXT_OIDS = new Set([
  types.builtins.DATE,
  types.builtins.TIMESTAMP,
  types.builtins.TIMESTAMPTZ,
]);

// pg-types types getTypeParser's return as `any`; pin it to avoid leaking `any`.
type ValueParser = (value: string) => unknown;
const getDefaultParser = types.getTypeParser as (
  oid: Parameters<typeof types.getTypeParser>[0],
  format?: Parameters<typeof types.getTypeParser>[1],
) => ValueParser;

const datasourceTypeParser: typeof types.getTypeParser = (oid, format) =>
  RAW_TEXT_OIDS.has(oid)
    ? (value: string) => value
    : getDefaultParser(oid, format);

@Injectable()
export class DataSourceService {
  constructor(private prisma: PrismaService) {}

  async create(userId: number, workspaceId: string, dto: CreateDataSourceDto) {
    return this.prisma.dataSource.create({
      data: {
        name: dto.name,
        host: dto.host,
        port: dto.port ?? 5432,
        database: dto.database,
        username: dto.username,
        password: encrypt(dto.password),
        sslEnabled: dto.sslEnabled ?? false,
        authorID: userId,
        workspaceId,
      },
    });
  }

  async findAllByWorkspace(workspaceId: string) {
    const datasources = await this.prisma.dataSource.findMany({
      where: { workspaceId },
      orderBy: { createdAt: 'desc' },
    });

    // Mask passwords
    return datasources.map((ds) => ({
      ...ds,
      password: '********',
    }));
  }

  async findOne(id: string) {
    const ds = await this.prisma.dataSource.findUnique({ where: { id } });
    if (!ds) {
      throw new NotFoundException('DataSource not found');
    }
    return { ...ds, password: '********' };
  }

  async update(id: string, dto: UpdateDataSourceDto) {
    const ds = await this.prisma.dataSource.findUnique({ where: { id } });
    if (!ds) {
      throw new NotFoundException('DataSource not found');
    }

    const data: Record<string, unknown> = {};
    if (dto.name !== undefined) data.name = dto.name;
    if (dto.host !== undefined) data.host = dto.host;
    if (dto.port !== undefined) data.port = dto.port;
    if (dto.database !== undefined) data.database = dto.database;
    if (dto.username !== undefined) data.username = dto.username;
    if (dto.password !== undefined) data.password = encrypt(dto.password);
    if (dto.sslEnabled !== undefined) data.sslEnabled = dto.sslEnabled;

    return this.prisma.dataSource.update({
      where: { id },
      data,
    });
  }

  async remove(id: string) {
    const ds = await this.prisma.dataSource.findUnique({ where: { id } });
    if (!ds) {
      throw new NotFoundException('DataSource not found');
    }
    return this.prisma.dataSource.delete({ where: { id } });
  }

  async testConnection(id: string) {
    const ds = await this.prisma.dataSource.findUnique({ where: { id } });
    if (!ds) {
      throw new NotFoundException('DataSource not found');
    }

    const client = this.createClient(ds);
    try {
      await client.connect();
      await client.query('SELECT 1');
      return { success: true };
    } catch (error) {
      return { success: false, error: (error as Error).message };
    } finally {
      await client.end().catch(() => {});
    }
  }

  async executeQuery(id: string, dto: ExecuteQueryDto) {
    const validation = validateSelectQuery(dto.query);
    if (!validation.valid) {
      throw new BadRequestException(validation.error);
    }

    const ds = await this.prisma.dataSource.findUnique({ where: { id } });
    if (!ds) {
      throw new NotFoundException('DataSource not found');
    }

    const client = this.createClient(ds);
    try {
      await client.connect();

      // Normalize output formatting only (not input parsing): UTC, ISO dates,
      // and C money — so results are deterministic across server locales.
      await client.query(`SET statement_timeout = '${QUERY_TIMEOUT_MS}'`);
      await client.query(`SET TimeZone = 'UTC'`);
      await client.query(`SET DateStyle = 'ISO'`);
      await client.query(`SET lc_monetary = 'C'`);

      // Wrap with LIMIT to enforce max rows
      const wrappedQuery = `SELECT * FROM (${dto.query}) AS _q LIMIT ${MAX_ROWS + 1}`;
      const startTime = Date.now();
      const result = await client.query(wrappedQuery);
      const executionTime = Date.now() - startTime;

      const truncated = result.rows.length > MAX_ROWS;
      const rows = truncated ? result.rows.slice(0, MAX_ROWS) : result.rows;

      return {
        columns: result.fields.map((f) => ({
          name: f.name,
          dataTypeID: f.dataTypeID,
        })),
        rows,
        rowCount: rows.length,
        truncated,
        executionTime,
      };
    } catch (error) {
      const pgError = error as { message?: string; code?: string };
      throw new BadRequestException(
        pgError.message || 'Query execution failed',
      );
    } finally {
      await client.end().catch(() => {});
    }
  }

  /**
   * Retrieve the raw datasource record (with workspaceId) for access
   * control checks in the controller layer.
   */
  async findRaw(id: string) {
    const ds = await this.prisma.dataSource.findUnique({ where: { id } });
    if (!ds) {
      throw new NotFoundException('DataSource not found');
    }
    return ds;
  }

  private createClient(ds: {
    host: string;
    port: number;
    database: string;
    username: string;
    password: string;
    sslEnabled: boolean;
  }): Client {
    return new Client({
      host: ds.host,
      port: ds.port,
      database: ds.database,
      user: ds.username,
      password: decrypt(ds.password),
      ssl: ds.sslEnabled ? { rejectUnauthorized: false } : false,
      connectionTimeoutMillis: 10_000,
      types: { getTypeParser: datasourceTypeParser },
    });
  }
}

import {
  Injectable,
  ForbiddenException,
  NotFoundException,
  GoneException,
  ConflictException,
} from '@nestjs/common';
import { PrismaService } from '../database/prisma.service';

@Injectable()
export class WorkspaceService {
  constructor(private prisma: PrismaService) {}

  async create(userId: number, data: { name: string }) {
    const slug = await this.generateUniqueSlug(data.name);
    const workspace = await this.prisma.workspace.create({
      data: { name: data.name, slug },
    });
    await this.prisma.workspaceMember.create({
      data: { workspaceId: workspace.id, userId, role: 'owner' },
    });
    return workspace;
  }

  async findAllByUser(userId: number) {
    const memberships = await this.prisma.workspaceMember.findMany({
      where: { userId },
      include: { workspace: true },
    });
    return memberships.map((m) => m.workspace);
  }

  async findOne(idOrSlug: string, userId: number) {
    const isUUID =
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        idOrSlug,
      );
    const workspace = await this.prisma.workspace.findUnique({
      where: isUUID ? { id: idOrSlug } : { slug: idOrSlug },
      include: {
        members: { include: { user: true } },
      },
    });
    if (!workspace) throw new NotFoundException('Workspace not found');
    const isMember = workspace.members.some((m) => m.userId === userId);
    if (!isMember)
      throw new ForbiddenException('Not a member of this workspace');
    return workspace;
  }

  async update(
    workspaceId: string,
    userId: number,
    data: { name?: string; slug?: string },
  ) {
    await this.assertOwner(workspaceId, userId);
    return this.prisma.workspace.update({
      where: { id: workspaceId },
      data,
    });
  }

  async remove(workspaceId: string, userId: number) {
    await this.assertOwner(workspaceId, userId);
    const workspaceCount = await this.prisma.workspaceMember.count({
      where: { userId },
    });
    if (workspaceCount <= 1) {
      throw new ForbiddenException('Cannot delete your last workspace');
    }
    return this.prisma.workspace.delete({ where: { id: workspaceId } });
  }

  async removeMember(
    workspaceId: string,
    requesterId: number,
    targetUserId: number,
  ) {
    if (requesterId !== targetUserId) {
      await this.assertOwner(workspaceId, requesterId);
    }
    const member = await this.prisma.workspaceMember.findUnique({
      where: { workspaceId_userId: { workspaceId, userId: targetUserId } },
    });
    if (!member) throw new NotFoundException('Member not found');
    if (member.role === 'owner' && requesterId === targetUserId) {
      throw new ForbiddenException('Owner cannot leave their own workspace');
    }
    return this.prisma.workspaceMember.delete({
      where: { workspaceId_userId: { workspaceId, userId: targetUserId } },
    });
  }

  async createInvite(
    workspaceId: string,
    userId: number,
    data: { role?: string; expiration?: string },
  ) {
    await this.assertOwner(workspaceId, userId);
    const expiresAt = data.expiration
      ? this.parseExpiration(data.expiration)
      : null;
    return this.prisma.workspaceInvite.create({
      data: {
        workspaceId,
        createdBy: userId,
        role: data.role || 'member',
        expiresAt,
      },
    });
  }

  async findInvites(workspaceId: string, userId: number) {
    await this.assertOwner(workspaceId, userId);
    return this.prisma.workspaceInvite.findMany({
      where: { workspaceId },
    });
  }

  async revokeInvite(
    workspaceId: string,
    inviteId: string,
    userId: number,
  ) {
    await this.assertOwner(workspaceId, userId);
    return this.prisma.workspaceInvite.delete({ where: { id: inviteId } });
  }

  async acceptInvite(token: string, userId: number) {
    const invite = await this.prisma.workspaceInvite.findUnique({
      where: { token },
    });
    if (!invite) throw new NotFoundException('Invite not found');
    if (invite.expiresAt && invite.expiresAt < new Date()) {
      throw new GoneException('Invite has expired');
    }
    const existing = await this.prisma.workspaceMember.findUnique({
      where: {
        workspaceId_userId: { workspaceId: invite.workspaceId, userId },
      },
    });
    if (existing) throw new ConflictException('Already a member');
    await this.prisma.workspaceMember.create({
      data: {
        workspaceId: invite.workspaceId,
        userId,
        role: invite.role,
      },
    });
    return { workspaceId: invite.workspaceId };
  }

  async resolveId(idOrSlug: string): Promise<string> {
    const isUUID =
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        idOrSlug,
      );
    if (isUUID) return idOrSlug;
    const workspace = await this.prisma.workspace.findUnique({
      where: { slug: idOrSlug },
      select: { id: true },
    });
    if (!workspace) throw new NotFoundException('Workspace not found');
    return workspace.id;
  }

  async assertMember(workspaceId: string, userId: number) {
    const resolvedId = await this.resolveId(workspaceId);
    const member = await this.prisma.workspaceMember.findUnique({
      where: { workspaceId_userId: { workspaceId: resolvedId, userId } },
    });
    if (!member)
      throw new ForbiddenException('Not a member of this workspace');
    return member;
  }

  async assertOwner(workspaceId: string, userId: number) {
    const resolvedId = await this.resolveId(workspaceId);
    const member = await this.prisma.workspaceMember.findUnique({
      where: { workspaceId_userId: { workspaceId: resolvedId, userId } },
    });
    if (!member || member.role !== 'owner') {
      throw new ForbiddenException(
        'Only workspace owner can perform this action',
      );
    }
    return member;
  }

  private parseExpiration(expiration: string): Date {
    const match = expiration.match(/^(\d+)([hd])$/);
    if (!match) throw new Error('Invalid expiration format');
    const [, value, unit] = match;
    const ms =
      unit === 'h' ? Number(value) * 3600000 : Number(value) * 86400000;
    return new Date(Date.now() + ms);
  }

  private generateSlug(name: string): string {
    return name
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
  }

  private async generateUniqueSlug(name: string): Promise<string> {
    const base = this.generateSlug(name);
    const existing = await this.prisma.workspace.findUnique({
      where: { slug: base },
    });
    if (!existing) return base;

    const suffix = Math.random().toString(36).slice(2, 6);
    return `${base}-${suffix}`;
  }
}

import {
  exportPptx,
  importPptx,
  type ImportReport,
  type SlidesDocument,
  type UploadImage,
} from "@wafflebase/slides";
import {
  docsImageFetcher,
  docsImageUploader,
  downloadBlob,
  pickFile,
  safeFilename,
} from "../docs/export-utils";

const PPTX_MIME =
  "application/vnd.openxmlformats-officedocument.presentationml.presentation";

const MIME_TO_EXT: Record<string, string> = {
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/gif": "gif",
  "image/webp": "webp",
  "image/bmp": "bmp",
};

/**
 * Bridge the slides importer's bytes+mime signature onto the shared
 * /images upload endpoint, which expects a `Blob` + filename. Reuses
 * `docsImageUploader` so PPTX images land in the same workspace bucket
 * as DOCX images.
 */
const slidesImageUploader: UploadImage = async (
  bytes: Uint8Array,
  mime: string,
): Promise<string> => {
  const ext = MIME_TO_EXT[mime] ?? "bin";
  const blob = new Blob([bytes], { type: mime });
  return docsImageUploader(blob, `image.${ext}`);
};

/**
 * Open the file picker for .pptx and parse the chosen archive. Returns
 * `null` if the user cancels. Throws on a malformed archive or a
 * failed image upload — the caller surfaces a toast and aborts the
 * document-creation flow.
 */
export async function pickAndImportPptx(
  onProgress?: (p: {
    done: number;
    total: number;
    fileName: string;
  }) => void,
): Promise<{
  document: SlidesDocument;
  report: ImportReport;
  fileName: string;
} | null> {
  const file = await pickFile(".pptx");
  if (!file) return null;
  const buffer = await file.arrayBuffer();
  const { document, report } = await importPptx(buffer, {
    uploadImage: slidesImageUploader,
    onProgress: onProgress
      ? (done, total) => onProgress({ done, total, fileName: file.name })
      : undefined,
  });
  return { document, report, fileName: file.name };
}

/**
 * Export the presentation to a `.pptx` archive and trigger a browser
 * download.
 *
 * Unlike the PDF path, PPTX is vector DrawingML XML — there is no canvas
 * raster step, so fonts need no preloading; PowerPoint resolves the family
 * names at open time. Images are embedded as `ppt/media/` parts: `exportPptx`
 * asks for each unique image `src`'s bytes through `fetchImage`, which we
 * satisfy with the same credentialed `docsImageFetcher` used by the docs and
 * slides PDF exporters (backend images are same-origin-fetched with cookies).
 *
 * `exportPptx` is re-exported from the browser entry of `@wafflebase/slides`
 * and is DOM-free, so it is safe to call from the editor. `onProgress` is
 * forwarded to the per-slide progress callback so the caller can drive an
 * export toast, mirroring the PDF path.
 */
export async function exportSlidesPptxAndDownload(
  doc: SlidesDocument,
  title: string,
  onProgress?: (done: number, total: number, phase: string) => void,
): Promise<void> {
  const bytes = await exportPptx(doc, {
    fetchImage: async (src) => {
      const blob = await docsImageFetcher(src);
      return {
        bytes: new Uint8Array(await blob.arrayBuffer()),
        mime: blob.type || "image/png",
      };
    },
    onProgress,
  });
  const blob = new Blob([bytes], { type: PPTX_MIME });
  downloadBlob(blob, safeFilename(title, "pptx"));
}

/**
 * PPTX export orchestrator.
 *
 * `exportPptx` assembles a complete `.pptx` archive from a `SlidesDocument`:
 *   1. Pre-scans all elements for image `src` values (deduped).
 *   2. Optionally fetches each image via `opts.fetchImage` and adds media parts.
 *   3. Emits theme / master / layout parts with the correct rel chain.
 *   4. Emits each slide part; wires slide→layout rels and image rels per slide.
 *   5. Emits `ppt/presentation.xml` with slide-id list and master-id list.
 *   6. Returns `writer.build()` — a complete in-memory zip as `Uint8Array`.
 *
 * ## Rel chain (mirrors what import/pptx/index.ts traverses)
 *   _rels/.rels              → ppt/presentation.xml (officeDocument)
 *   ppt/_rels/presentation.xml.rels
 *     → ppt/theme/theme1.xml     (theme)
 *     → ppt/slideMasters/slideMaster1.xml  (slideMaster)
 *     → ppt/slides/slideN.xml    (slide, one per slide)
 *   ppt/slideMasters/_rels/slideMaster1.xml.rels
 *     → ppt/theme/theme1.xml     (theme)
 *     → ppt/slideLayouts/slideLayoutN.xml  (slideLayout, one per layout)
 *   ppt/slideLayouts/_rels/slideLayoutN.xml.rels
 *     → ppt/slideMasters/slideMaster1.xml  (slideMaster)
 *   ppt/slides/_rels/slideN.xml.rels
 *     → ppt/slideLayouts/slideLayoutM.xml  (slideLayout — the slide's layout)
 *     → ppt/media/imageK.{ext}             (image, one per image element)
 *
 * ## Image handling
 *   If `opts.fetchImage` is absent and a slide has image elements whose `src`
 *   is a data-URL or remote URL that cannot be resolved at build time, we
 *   throw a clear error rather than silently writing broken rId references.
 *   Callers that don't need images can pass a deck with no image elements and
 *   omit `opts.fetchImage`.
 *
 * ## Content types added
 *   - presentation.xml:    presentationml.presentation.main+xml
 *   - theme/themeN.xml:    theme+xml
 *   - slideMasters/…:      presentationml.slideMaster+xml
 *   - slideLayouts/…:      presentationml.slideLayout+xml
 *   - slides/slideN.xml:   presentationml.slide+xml
 *   - slides/notesN.xml:   presentationml.notesSlide+xml
 */

import type { SlidesDocument } from '../../model/presentation.js';
import { resolveBackgroundFill } from '../../model/presentation.js';
import { yieldToPaint } from '../yield.js';
import type { ImageElement } from '../../model/element.js';
import { flattenElements, buildElementWorldLookup } from '../../model/group.js';
import { computeConnectorFrame } from '../../view/canvas/connector-frame.js';
import { PptxWriter } from './zip.js';
import { REL_TYPES } from './templates.js';
import { themeToXml } from './theme.js';
import { masterToXml } from './master.js';
import { layoutToXml } from './layout.js';
import { slideToXml, notesSlideToXml } from './slide.js';
import { presentationToXml } from './presentation.js';
import type { ElementXmlCtx } from './group.js';

// ---------------------------------------------------------------------------
// Public interface
// ---------------------------------------------------------------------------

export interface ExportPptxOptions {
  /**
   * Called once per unique image `src` across all slides. Must return the
   * raw image bytes and MIME type so the exporter can embed the file in the
   * `ppt/media/` directory.
   *
   * Required if the deck contains `ImageElement` elements. Omit only when
   * the deck has no images — attempting to export a deck with images without
   * this option throws a clear error rather than writing broken XML.
   */
  fetchImage?: (src: string) => Promise<{ bytes: Uint8Array; mime: string }>;
  /** Progress callback: `(done, total, 'slides')` once before work, then after each serialized slide. */
  onProgress?: (done: number, total: number, phase: string) => void;
}

// ---------------------------------------------------------------------------
// MIME → file extension helper
// ---------------------------------------------------------------------------

/** Map a MIME type to the file extension used in `ppt/media/`. */
function extFromMime(mime: string): string {
  switch (mime.toLowerCase()) {
    case 'image/png':
      return 'png';
    case 'image/jpeg':
    case 'image/jpg':
      return 'jpg';
    case 'image/gif':
      return 'gif';
    case 'image/webp':
      return 'webp';
    case 'image/bmp':
      return 'bmp';
    default:
      return 'png';
  }
}

// ---------------------------------------------------------------------------
// Content-type constants
// ---------------------------------------------------------------------------

const CT_PRESENTATION =
  'application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml';
const CT_THEME =
  'application/vnd.openxmlformats-officedocument.theme+xml';
const CT_SLIDE_MASTER =
  'application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml';
const CT_SLIDE_LAYOUT =
  'application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml';
const CT_SLIDE =
  'application/vnd.openxmlformats-officedocument.presentationml.slide+xml';
const CT_NOTES =
  'application/vnd.openxmlformats-officedocument.presentationml.notesSlide+xml';

// ---------------------------------------------------------------------------
// Main orchestrator
// ---------------------------------------------------------------------------

/**
 * Export a `SlidesDocument` to a `.pptx` binary (zip archive) returned as
 * `Uint8Array`. The bytes can be written directly to a file or served as a
 * download response.
 *
 * Node consumers should import this from `@wafflebase/slides/node`. Browser
 * consumers can import from `@wafflebase/slides` (same symbol, same code —
 * the orchestrator itself is DOM-free).
 */
export async function exportPptx(
  deck: SlidesDocument,
  opts: ExportPptxOptions = {},
): Promise<Uint8Array> {
  const writer = new PptxWriter();

  // -------------------------------------------------------------------------
  // Step 1: Pre-scan all image elements across all slides (dedup by src).
  // -------------------------------------------------------------------------
  const allImageSrcs = new Set<string>();
  for (const slide of deck.slides) {
    for (const el of flattenElements(slide.elements)) {
      if (el.type === 'image') {
        allImageSrcs.add(el.data.src);
      }
    }
  }

  // -------------------------------------------------------------------------
  // Step 2: Fetch + add media; build src→mediaPath map.
  // -------------------------------------------------------------------------
  // src → the relative path under ppt/ (e.g. "media/image1.png")
  const srcToMediaPath = new Map<string, string>();

  if (allImageSrcs.size > 0) {
    if (!opts.fetchImage) {
      throw new Error(
        'exportPptx: deck contains image elements but `opts.fetchImage` is not provided. ' +
          'Supply a `fetchImage` implementation that returns { bytes, mime } for each image src.',
      );
    }
    for (const src of allImageSrcs) {
      const { bytes, mime } = await opts.fetchImage(src);
      const ext = extFromMime(mime);
      const mediaPath = writer.addMedia(bytes, ext);
      srcToMediaPath.set(src, mediaPath);
    }
  }

  // -------------------------------------------------------------------------
  // Step 3: Theme parts.
  //
  // The importer picks up the theme via a `theme` rel from
  // ppt/presentation.xml. We emit the deck's first theme (which, after an
  // import, is the imported theme). If there are no themes at all, fall back
  // to the built-in default-light via a minimal synthetic XML — importPptx
  // always populates at least BUILT_IN_THEMES so this path should be rare.
  // -------------------------------------------------------------------------
  const themes = deck.themes.length > 0 ? deck.themes.slice(0, 1) : [];
  const themePaths: string[] = [];
  for (let i = 0; i < themes.length; i++) {
    const theme = themes[i];
    const themePath = `ppt/theme/theme${i + 1}.xml`;
    writer.addPart(themePath, themeToXml(theme, i + 1), CT_THEME);
    themePaths.push(themePath);
  }

  // If no theme was available (extremely unlikely), emit a placeholder path
  // so the rest of the wiring doesn't need to branch.
  const primaryThemePath = themePaths[0] ?? null;

  // -------------------------------------------------------------------------
  // Step 4: Master + layout parts.
  //
  // We emit one master (the deck's first master or DEFAULT_MASTER) and all
  // layouts whose masterId matches. The rel chain expected by the importer:
  //   presentation → master (slideMaster)
  //   master → theme (theme)
  //   master → each layout (slideLayout)
  //   layout → master (slideMaster)
  //   slide → one layout (slideLayout)
  // -------------------------------------------------------------------------
  const masterObj = deck.masters.length > 0 ? deck.masters[0] : null;

  // Collect layouts for the single emitted master.
  const masterId = masterObj?.id ?? 'default';
  const masterLayouts = deck.layouts.filter((l) => l.masterId === masterId);
  // If there are no layouts for this master, emit at least one (blank)
  // so the archive is always valid.
  let layoutsToEmit = masterLayouts.length > 0 ? masterLayouts : deck.layouts.slice(0, 1);

  // Final guard: if the deck has no layouts at all, synthesise a minimal blank
  // layout so every slide's layout rel resolves to a valid part.
  const useFallbackLayout = layoutsToEmit.length === 0;
  const FALLBACK_LAYOUT_ID = '__fallback_blank__';

  const masterPath = 'ppt/slideMasters/slideMaster1.xml';

  // Emit master XML.
  const masterXml = masterObj
    ? masterToXml(masterObj, 0)
    : fallbackMasterXml();
  writer.addPart(masterPath, masterXml, CT_SLIDE_MASTER);

  // Emit layout XMLs and build layoutId → layoutPath map.
  const layoutIdToPath = new Map<string, string>();

  if (useFallbackLayout) {
    // No layouts at all — emit a single minimal blank layout so every slide's
    // layout rel resolves to a valid part.
    const layoutPath = 'ppt/slideLayouts/slideLayout1.xml';
    writer.addPart(layoutPath, fallbackLayoutXml(), CT_SLIDE_LAYOUT);
    layoutIdToPath.set(FALLBACK_LAYOUT_ID, layoutPath);
    writer.addRel(layoutPath, REL_TYPES.slideMaster, '../slideMasters/slideMaster1.xml');
  } else {
    for (let i = 0; i < layoutsToEmit.length; i++) {
      const layout = layoutsToEmit[i];
      const layoutPath = `ppt/slideLayouts/slideLayout${i + 1}.xml`;
      writer.addPart(layoutPath, layoutToXml(layout, i + 1), CT_SLIDE_LAYOUT);
      layoutIdToPath.set(layout.id, layoutPath);

      // layout → master rel
      writer.addRel(layoutPath, REL_TYPES.slideMaster, '../slideMasters/slideMaster1.xml');
    }
  }

  // master → theme rel (importer looks for this via `pickRelTarget(presRels,'theme')` on
  // ppt/presentation.xml, but also the master carries a theme rel for color mapping).
  if (primaryThemePath) {
    writer.addRel(masterPath, REL_TYPES.theme, '../theme/theme1.xml');
  }

  // master → layout rels
  if (useFallbackLayout) {
    writer.addRel(masterPath, REL_TYPES.slideLayout, '../slideLayouts/slideLayout1.xml');
  } else {
    for (let i = 0; i < layoutsToEmit.length; i++) {
      writer.addRel(
        masterPath,
        REL_TYPES.slideLayout,
        `../slideLayouts/slideLayout${i + 1}.xml`,
      );
    }
  }

  // -------------------------------------------------------------------------
  // Step 5: Slide parts — emit each slide, wire image + layout rels.
  // -------------------------------------------------------------------------
  const slideRIds: string[] = [];

  const onProgress = opts.onProgress;
  const slideTotal = deck.slides.length;
  onProgress?.(0, slideTotal, 'slides');

  for (let i = 0; i < slideTotal; i++) {
    const slide = deck.slides[i];
    const slidePath = `ppt/slides/slide${i + 1}.xml`;

    // Build the world-element lookup for connector geometry.
    const worldLookup = buildElementWorldLookup(slide.elements);

    // Build per-slide image rId resolver.
    // src → rId is slide-local (each slide has its own .rels file).
    const slideImageRIdCache = new Map<string, string>();
    function resolveImageRId(el: ImageElement): string {
      const src = el.data.src;
      const cached = slideImageRIdCache.get(src);
      if (cached) return cached;
      const mediaPath = srcToMediaPath.get(src);
      if (!mediaPath) {
        // Image src is not in the pre-scan map — this should not happen if all
        // elements were scanned, but guard with a clear error rather than an
        // invalid r:embed="" attribute.
        throw new Error(
          `exportPptx: image src not found in media map: ${src.slice(0, 120)}`,
        );
      }
      // Add an image rel for this slide (target is relative to slide's dir).
      const rId = writer.addRel(slidePath, REL_TYPES.image, `../${mediaPath}`);
      slideImageRIdCache.set(src, rId);
      return rId;
    }

    const ctx: ElementXmlCtx = {
      resolveImageRId,
      connectorFrame: (el) => computeConnectorFrame(el, worldLookup),
    };

    // Always serialize the *resolved* effective fill (slide → layout →
    // master → role) so master/layout background edits round-trip. A real
    // slide override returns itself; an inheriting slide — whether it has
    // no fill OR a bare `{role:'background'}` fill (the legacy default,
    // which resolveBackgroundFill also treats as inherit) — resolves to
    // the master/layout color. Background *images* are still not exported
    // (see backgroundToXml).
    const slideForXml = {
      ...slide,
      background: {
        ...slide.background,
        fill: resolveBackgroundFill(slide, deck),
      },
    };

    // Emit slide XML.
    writer.addPart(slidePath, slideToXml(slideForXml, ctx), CT_SLIDE);

    // Determine this slide's layout. Fall back to first layout or blank.
    const resolvedLayoutPath =
      layoutIdToPath.get(slide.layoutId) ?? 'ppt/slideLayouts/slideLayout1.xml';

    // Image rels are added during slideToXml() via resolveImageRId.
    // Add the layout rel after so it follows any image rels in rId order.
    writer.addRel(slidePath, REL_TYPES.slideLayout, `../${resolvedLayoutPath.slice('ppt/'.length)}`);

    // Notes slide — if the slide has non-empty notes, emit a notes part.
    if (slide.notes && slide.notes.length > 0) {
      const notesPath = `ppt/notesSlides/notesSlide${i + 1}.xml`;
      writer.addPart(notesPath, notesSlideToXml(slide.notes), CT_NOTES);
      writer.addRel(slidePath, REL_TYPES.notesSlide, `../notesSlides/notesSlide${i + 1}.xml`);
    }

    // Collect the rId for this slide in presentation.xml.rels (added below).
    const slideRId = writer.addRel(
      'ppt/presentation.xml',
      REL_TYPES.slide,
      `slides/slide${i + 1}.xml`,
    );
    slideRIds.push(slideRId);
    onProgress?.(i + 1, slideTotal, 'slides');
    // Only yield on the interactive (progress-reporting) path; headless/CLI
    // exports gain nothing from the extra event-loop turn per slide.
    if (onProgress && i + 1 < slideTotal) await yieldToPaint();
  }

  // -------------------------------------------------------------------------
  // Step 6: presentation.xml → master rel + theme rel.
  // -------------------------------------------------------------------------
  const masterRId = writer.addRel(
    'ppt/presentation.xml',
    REL_TYPES.slideMaster,
    'slideMasters/slideMaster1.xml',
  );

  if (primaryThemePath) {
    writer.addRel('ppt/presentation.xml', REL_TYPES.theme, 'theme/theme1.xml');
  }

  // -------------------------------------------------------------------------
  // Step 7: presentation.xml part.
  // -------------------------------------------------------------------------
  writer.addPart(
    'ppt/presentation.xml',
    presentationToXml(deck, slideRIds, masterRId),
    CT_PRESENTATION,
  );

  // -------------------------------------------------------------------------
  // Step 8: Build and return the zip.
  // -------------------------------------------------------------------------
  return writer.build();
}

// ---------------------------------------------------------------------------
// Fallback layout XML (used when the deck has no layouts at all)
// ---------------------------------------------------------------------------

/**
 * Emit a bare-minimum blank slide layout when the deck has no layout records.
 * This ensures every slide's layout rel resolves to a valid part even for
 * programmatically constructed decks that omit layout data.
 */
function fallbackLayoutXml(): string {
  return (
    `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>` +
    `<p:sldLayout` +
    ` xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"` +
    ` xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"` +
    ` xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"` +
    ` type="blank"` +
    `>` +
    `<p:cSld>` +
    `<p:spTree>` +
    `<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>` +
    `<p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr>` +
    `</p:spTree>` +
    `</p:cSld>` +
    `<p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr>` +
    `</p:sldLayout>`
  );
}

// ---------------------------------------------------------------------------
// Fallback master XML (used when the deck has no masters at all — rare)
// ---------------------------------------------------------------------------

/**
 * Emit a bare-minimum slide master when the deck has no master records.
 * This avoids a crash while still producing a structurally valid archive.
 */
function fallbackMasterXml(): string {
  return (
    `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>` +
    `<p:sldMaster` +
    ` xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"` +
    ` xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"` +
    ` xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"` +
    `>` +
    `<p:cSld>` +
    `<p:bg><p:bgPr><a:solidFill><a:schemeClr val="bg1"/></a:solidFill></p:bgPr></p:bg>` +
    `<p:spTree>` +
    `<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>` +
    `<p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr>` +
    `</p:spTree>` +
    `</p:cSld>` +
    `<p:clrMap bg1="lt1" tx1="dk1" bg2="lt2" tx2="dk2" accent1="accent1" accent2="accent2" accent3="accent3" accent4="accent4" accent5="accent5" accent6="accent6" hlink="hlink" folHlink="folHlink"/>` +
    `<p:sldLayoutIdLst/>` +
    `</p:sldMaster>`
  );
}

/**
 * Slides PDF export — P0 raster pipeline.
 *
 * Renders every slide through the *existing* `drawSlide()` canvas
 * pipeline (so shapes, images, tables, connectors, groups, effects,
 * theme colors and background images all match the editor exactly) onto
 * a high-DPI offscreen canvas, then embeds one bitmap per page into a
 * `pdf-lib` document sized 13.333" × 7.5" (the default 16:9 deck).
 *
 * Why raster, not vector: the docs `PdfPainter` only knows paragraphs /
 * tables / images, whereas a slide carries 100+ shape kinds, freeform
 * paths, connectors, rotations and effects. Reusing the canvas renderer
 * is pixel-identical for a fraction of the effort. Trade-off: PDF text
 * is not selectable (a vector text overlay is the planned P1). See
 * `docs/design/slides/slides-pdf-export.md`.
 *
 * Cross-origin tainting: production serves images from a different
 * origin and the editor loads them via a plain `img.src` (no CORS), so
 * drawing them and then calling `toBlob` would taint the canvas and
 * throw. The exporter therefore fetches each image's bytes (with
 * credentials, via the injected `imageFetcher`) into a same-origin
 * object URL, clones each slide with the rewritten srcs, and renders the
 * clone — the editor's slides and shared image cache are never mutated.
 *
 * Browser-only: depends on DOM `Image`, `OffscreenCanvas`/`<canvas>` and
 * `document.fonts`. Node consumers cannot use this entry.
 */
import type { Element, TextBody } from '../model/element';
import type {
  BackgroundImage,
  Slide,
  SlidesDocument,
} from '../model/presentation';
import {
  SLIDE_HEIGHT,
  SLIDE_WIDTH,
  resolveBackgroundImage,
} from '../model/presentation';
import { drawSlide } from '../view/canvas/slide-renderer';
import {
  evictImageSrcs,
  getOrLoadImage,
  isImageFailed,
} from '../view/canvas/image-cache';
import { yieldToPaint } from './yield';

/**
 * Fetches the raw bytes of an image `src`. Supplied by the frontend so
 * the export can pull cross-origin (backend-hosted) images with auth
 * cookies into a taint-free object URL. Omit it only for decks whose
 * images are all `data:`/`blob:` (e.g. tests) or genuinely same-origin.
 */
export type SlidesImageFetcher = (src: string) => Promise<Blob>;

export interface ExportSlidesPdfOptions {
  /**
   * Bitmap supersampling factor per slide. Default `2` →
   * 3840 × 2160 source bitmap, scaled into the 960 × 540 pt page so
   * text / shape edges stay crisp. Geometry is unaffected — only
   * sharpness and file size scale with this.
   */
  scale?: number;
  /** Encoding of the per-page bitmap. `'png'` (default, lossless) or `'jpeg'` (smaller, photo-heavy decks). */
  format?: 'png' | 'jpeg';
  /** JPEG quality `0..1`. Default `0.92`. Ignored for PNG. */
  quality?: number;
  /** Fetch http(s) image bytes with credentials to avoid canvas tainting. */
  imageFetcher?: SlidesImageFetcher;
  /** Per-slide image-load timeout in ms before painting with whatever loaded. Default `15000`. */
  assetTimeoutMs?: number;
  /** Title written into the PDF metadata. */
  title?: string;
  /** Progress callback: `(done, total, 'slides')` once before work, then after each rendered slide. */
  onProgress?: (done: number, total: number, phase: string) => void;
}

// 1×1 transparent PNG. Used as a taint-free stand-in for images whose
// bytes could not be fetched, so a broken/forbidden URL renders blank
// instead of either tainting the canvas (original cross-origin src) or
// hanging on an unreliable empty-src `onerror`.
const BLANK_PNG =
  'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HBwCAAAAC0lEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==';

// PDF page width in points for the default 16:9 deck (13.333" × 72).
const PAGE_WIDTH_PT = 960;

type ExportCanvas = OffscreenCanvas | HTMLCanvasElement;

/**
 * Export the whole presentation as a multi-page PDF (one slide per
 * page) and return the encoded bytes. Callers wrap the result in a
 * `Blob` and trigger a download.
 *
 * The caller is responsible for ensuring every font the deck uses is
 * loaded into `document.fonts` before calling (see
 * {@link collectFontFamilies}); the exporter awaits `document.fonts.ready`
 * defensively but cannot initiate lazy font CSS itself.
 */
export async function exportSlidesPdf(
  doc: SlidesDocument,
  opts: ExportSlidesPdfOptions = {},
): Promise<Uint8Array> {
  if (doc.slides.length === 0) {
    throw new Error('Cannot export an empty presentation to PDF.');
  }

  const scale = opts.scale ?? 2;
  const format = opts.format ?? 'png';
  const quality = opts.quality ?? 0.92;
  const assetTimeoutMs = opts.assetTimeoutMs ?? 15000;

  // Dynamic import keeps pdf-lib (~150 KB) out of the editor bundle —
  // it loads only when the user actually exports.
  const { PDFDocument } = await import('pdf-lib');
  const pdf = await PDFDocument.create();
  if (opts.title) pdf.setTitle(opts.title);

  // Resolve any font loads the caller kicked off so text measures and
  // paints with the intended glyphs rather than a fallback.
  if (typeof document !== 'undefined' && document.fonts?.ready) {
    try {
      await document.fonts.ready;
    } catch {
      /* font readiness is best-effort */
    }
  }

  const { map, temp } = await resolveDeckImages(doc, opts.imageFetcher);
  const pageWidth = PAGE_WIDTH_PT;
  const pageHeight = (SLIDE_HEIGHT / SLIDE_WIDTH) * PAGE_WIDTH_PT;

  const onProgress = opts.onProgress;
  const total = doc.slides.length;

  try {
    // Emit inside the try so a throwing callback can't skip the finally that
    // revokes the temp object URLs allocated by resolveDeckImages() above.
    let done = 0;
    onProgress?.(0, total, 'slides');
    for (const slide of doc.slides) {
      const cloned = prepareExportSlide(slide, doc, map);

      // Preload this slide's (now taint-free) image srcs so the single
      // paint below draws them instead of skipping still-loading ones.
      const srcs = imageSrcsToPreload(cloned);
      await Promise.all(srcs.map((s) => awaitImageLoaded(s, assetTimeoutMs)));

      const canvas = createExportCanvas(
        Math.round(SLIDE_WIDTH * scale),
        Math.round(SLIDE_HEIGHT * scale),
      );
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        throw new Error('Failed to acquire a 2D context for PDF export.');
      }
      drawSlide(ctx as unknown as CanvasRenderingContext2D, cloned, doc, {
        hostWidth: SLIDE_WIDTH,
        hostHeight: SLIDE_HEIGHT,
        dpr: scale,
      });

      const bytes = await canvasToBytes(canvas, format, quality);
      const image =
        format === 'jpeg' ? await pdf.embedJpg(bytes) : await pdf.embedPng(bytes);
      const page = pdf.addPage([pageWidth, pageHeight]);
      page.drawImage(image, { x: 0, y: 0, width: pageWidth, height: pageHeight });

      done += 1;
      onProgress?.(done, total, 'slides');
      // Only yield when progress is being reported — i.e. the interactive
      // (browser) path. Headless/CLI exports gain nothing from the extra
      // event-loop turn.
      if (onProgress && done < total) await yieldToPaint();
    }
  } finally {
    if (temp.length > 0) {
      evictImageSrcs(temp);
      for (const url of temp) URL.revokeObjectURL(url);
    }
  }

  return pdf.save();
}

/**
 * Every distinct font family the deck references — the two theme fonts
 * (heading/body) per theme plus every explicit inline `fontFamily`.
 * The frontend loads each into `document.fonts` before export so
 * un-viewed slides (whose lazy Google Fonts never loaded) still render
 * with the right glyphs.
 */
export function collectFontFamilies(doc: SlidesDocument): string[] {
  const families = new Set<string>();
  for (const theme of doc.themes) {
    if (theme.fonts?.heading) families.add(theme.fonts.heading);
    if (theme.fonts?.body) families.add(theme.fonts.body);
  }
  for (const slide of doc.slides) {
    for (const el of flattenElements(slide.elements)) {
      for (const body of textBodiesOf(el)) {
        for (const block of body.blocks) {
          // List-item bullets can carry their own font (PPTX `<a:buFont>`),
          // painted by the docs marker path independent of the inlines.
          if (block.marker?.fontFamily) families.add(block.marker.fontFamily);
          for (const inline of block.inlines) {
            if (inline.style.fontFamily) families.add(inline.style.fontFamily);
          }
        }
      }
    }
  }
  return Array.from(families);
}

// --- internals ------------------------------------------------------

/** Flatten the element tree, recursing into groups, into a single list. */
function flattenElements(elements: readonly Element[]): Element[] {
  const out: Element[] = [];
  const walk = (list: readonly Element[]): void => {
    for (const el of list) {
      out.push(el);
      if (el.type === 'group') walk(el.data.children);
    }
  };
  walk(elements);
  return out;
}

/** Every text body carried by an element (text box, shape text, table cells). */
function textBodiesOf(el: Element): TextBody[] {
  if (el.type === 'text') return [el.data];
  if (el.type === 'shape') return el.data.text ? [el.data.text] : [];
  if (el.type === 'table') {
    const bodies: TextBody[] = [];
    for (const row of el.data.rows) {
      for (const cell of row.cells) bodies.push(cell.body);
    }
    return bodies;
  }
  return [];
}


/**
 * Pull every cross-origin image in the deck into a taint-free object
 * URL, returning a `src → usableSrc` map plus the temp URLs to revoke.
 * `data:`/`blob:` srcs pass through untouched; fetch failures map to a
 * blank PNG so a forbidden URL renders empty rather than tainting.
 */
async function resolveDeckImages(
  doc: SlidesDocument,
  fetcher: SlidesImageFetcher | undefined,
): Promise<{ map: Map<string, string>; temp: string[] }> {
  const originals = new Set<string>();
  for (const slide of doc.slides) {
    for (const el of flattenElements(slide.elements)) {
      if (el.type === 'image' && el.data.src) originals.add(el.data.src);
    }
    const bg = resolveBackgroundImage(slide, doc)?.src;
    if (bg) originals.add(bg);
  }

  // Fetch all images concurrently — they are independent, and a deck
  // with many cross-origin images would otherwise pay one round-trip
  // of latency per image.
  const entries = await Promise.all(
    Array.from(originals).map(async (src) => {
      if (src.startsWith('data:') || src.startsWith('blob:')) {
        return { src, url: src, temp: false };
      }
      if (!fetcher) {
        // No fetcher: best-effort. Same-origin srcs render fine; a
        // cross-origin one would taint, but that is the caller's contract.
        return { src, url: src, temp: false };
      }
      try {
        const blob = await fetcher(src);
        return { src, url: URL.createObjectURL(blob), temp: true };
      } catch {
        return { src, url: BLANK_PNG, temp: false };
      }
    }),
  );

  const map = new Map<string, string>();
  const temp: string[] = [];
  for (const entry of entries) {
    map.set(entry.src, entry.url);
    if (entry.temp) temp.push(entry.url);
  }
  return { map, temp };
}

/**
 * Deep-clone a slide into the form the exporter should rasterise:
 *   - every image src rewritten to its taint-free URL;
 *   - the deck master's background image (used when the slide has none
 *     of its own) resolved onto the clone so `drawSlide` never reaches
 *     the original cross-origin master src;
 *   - `placeholderRef` stripped from every element so empty placeholders
 *     do NOT paint their editor-only "Click to add title" ghost hint
 *     into the PDF. The hint is the sole render-path consumer of
 *     `placeholderRef` (element-renderer's `text` case), and real
 *     placeholder text bakes its typography into the blocks, so dropping
 *     the ref only suppresses the hint.
 */
function prepareExportSlide(
  slide: Slide,
  doc: SlidesDocument,
  map: Map<string, string>,
): Slide {
  const cloned = structuredClone(slide) as Slide;
  for (const el of flattenElements(cloned.elements)) {
    delete el.placeholderRef;
    if (el.type === 'image' && el.data.src) {
      el.data.src = map.get(el.data.src) ?? el.data.src;
    }
  }
  if (cloned.background.image) {
    cloned.background.image.src =
      map.get(cloned.background.image.src) ?? cloned.background.image.src;
  } else {
    // Bake the inherited (layout → master) background image onto the
    // cloned slide so the offscreen raster sees it directly.
    const inheritedBg = resolveBackgroundImage(slide, doc);
    if (inheritedBg) {
      const clonedBg = structuredClone(inheritedBg) as BackgroundImage;
      clonedBg.src = map.get(inheritedBg.src) ?? inheritedBg.src;
      cloned.background.image = clonedBg;
    }
  }
  return cloned;
}

/** Image srcs to preload before painting a (cleaned) slide. */
function imageSrcsToPreload(slide: Slide): string[] {
  const srcs: string[] = [];
  for (const el of flattenElements(slide.elements)) {
    if (el.type === 'image' && el.data.src) srcs.push(el.data.src);
  }
  if (slide.background.image?.src) srcs.push(slide.background.image.src);
  return srcs;
}

/**
 * Resolve once `src` is loaded (or failed, or the timeout elapses).
 * Wraps the event-driven shared image cache in a promise so the single
 * paint can run after all assets settle.
 */
function awaitImageLoaded(src: string, timeoutMs: number): Promise<void> {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (): void => {
      if (!settled) {
        settled = true;
        resolve();
      }
    };
    const img = getOrLoadImage(src, finish);
    if (img !== null || isImageFailed(src)) {
      finish();
      return;
    }
    if (timeoutMs > 0) setTimeout(finish, timeoutMs);
  });
}

function createExportCanvas(width: number, height: number): ExportCanvas {
  if (typeof OffscreenCanvas !== 'undefined') {
    return new OffscreenCanvas(width, height);
  }
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  return canvas;
}

async function canvasToBytes(
  canvas: ExportCanvas,
  format: 'png' | 'jpeg',
  quality: number,
): Promise<Uint8Array> {
  const type = format === 'jpeg' ? 'image/jpeg' : 'image/png';
  let blob: Blob;
  if (typeof OffscreenCanvas !== 'undefined' && canvas instanceof OffscreenCanvas) {
    blob = await canvas.convertToBlob({ type, quality });
  } else {
    blob = await new Promise<Blob>((resolve, reject) => {
      (canvas as HTMLCanvasElement).toBlob(
        (b) => (b ? resolve(b) : reject(new Error('canvas.toBlob returned null'))),
        type,
        quality,
      );
    });
  }
  return new Uint8Array(await blob.arrayBuffer());
}

import type { ImageFetcher, ImageUploader } from "@wafflebase/docs";
import { fetchWithAuth } from "@/api/auth";
import { toast } from "sonner";

const BACKEND_BASE = import.meta.env.VITE_BACKEND_API_URL ?? "";

/**
 * Resolve a possibly-relative image URL (e.g. "/images/<id>") against the
 * backend base URL so the browser can fetch it from a different origin /
 * port than the frontend.
 */
export function resolveImageUrl(url: string): string {
  // Preserve any absolute URL — http(s):, data:, blob:, file:, etc.
  // Only relative paths get prefixed with the backend base.
  if (/^[a-z][a-z0-9+.-]*:/i.test(url)) return url;
  if (!BACKEND_BASE) return url;
  return `${BACKEND_BASE.replace(/\/$/, "")}${url.startsWith("/") ? url : `/${url}`}`;
}

/**
 * Uploads an image blob to the backend ImageModule and returns
 * the absolute URL the docs canvas can render. Used by both DOCX
 * import and any future direct image-insertion path.
 */
export const docsImageUploader: ImageUploader = async (
  blob: Blob,
  filename: string,
): Promise<string> => {
  const formData = new FormData();
  formData.append("file", blob, filename);
  const res = await fetchWithAuth(`${BACKEND_BASE}/images`, {
    method: "POST",
    body: formData,
  });
  if (!res.ok) {
    throw new Error(`Image upload failed: ${res.status} ${res.statusText}`);
  }
  const { url } = (await res.json()) as { id: string; url: string };
  return resolveImageUrl(url);
};

/**
 * Downloads an image blob referenced by a docs image inline. Sends
 * cookies so backend-hosted (per-workspace) images are reachable.
 */
export const docsImageFetcher: ImageFetcher = async (
  url: string,
): Promise<Blob> => {
  const resolved = resolveImageUrl(url);
  // Use credentials so JWT cookies are sent for backend-hosted images.
  const res = await fetch(resolved, { credentials: "include" });
  if (!res.ok) {
    throw new Error(`Image fetch failed: ${res.status} ${res.statusText}`);
  }
  return res.blob();
};

/**
 * Trigger a browser download for the given blob with the given filename.
 */
export function downloadBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  // Defer revocation so Safari has a chance to start the download.
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/**
 * Open a native file picker (single file). Resolves to the selected file
 * or null if the user cancels. The hidden input is appended to the DOM
 * so it works reliably across browsers.
 */
export function pickFile(accept: string): Promise<File | null> {
  return new Promise((resolve) => {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = accept;
    input.style.display = "none";
    let settled = false;

    input.onchange = () => {
      settled = true;
      const file = input.files?.[0] ?? null;
      cleanup();
      resolve(file);
    };

    // Detect cancel via window focus (no perfect way, but acceptable).
    const onFocus = () => {
      window.removeEventListener("focus", onFocus);
      setTimeout(() => {
        if (!settled) {
          cleanup();
          resolve(null);
        }
      }, 300);
    };
    window.addEventListener("focus", onFocus);

    const cleanup = () => {
      if (input.parentNode) input.parentNode.removeChild(input);
    };

    document.body.appendChild(input);
    input.click();
  });
}

/**
 * Lazily create (first tick) or update the export progress toast, mirroring
 * the import toast. `unit` is the exporter's phase string ("slides" | "pages"
 * | "images"). Returns the toast id so the caller can thread it to
 * success/error. Returns `undefined` when there is nothing to show yet (a
 * zero-unit export, e.g. an image-less DOCX) so the caller falls back to a
 * fresh success/error toast instead of flashing a descriptionless spinner.
 */
export function updateExportToast(
  toastId: string | number | undefined,
  title: string,
  done: number,
  total: number,
  unit: string,
): string | number | undefined {
  const description =
    total > 0 ? `${Math.min(done, total)} / ${total} ${unit}` : undefined;
  if (toastId === undefined) {
    // Nothing to report yet (total 0) — don't create a loading toast that
    // would immediately be replaced by success, producing a visible flash.
    if (total === 0) return undefined;
    return toast.loading(`Exporting "${title}"…`, { description });
  }
  toast.loading(`Exporting "${title}"…`, { id: toastId, description });
  return toastId;
}

/**
 * Build a filesystem-safe filename for export downloads.
 * Adds the extension if not already present.
 */
export function safeFilename(
  title: string,
  ext: "docx" | "pdf" | "pptx",
): string {
  // Strip filesystem-unsafe characters; if nothing usable is left,
  // fall back to "document" so we don't return a hidden file like ".pdf".
  const sanitized = (title || "").replace(/[\\/:*?"<>|]+/g, "_").trim();
  const safe = sanitized || "document";
  return safe.toLowerCase().endsWith(`.${ext}`) ? safe : `${safe}.${ext}`;
}

const FORBIDDEN_KEYWORDS = [
  'INSERT',
  'UPDATE',
  'DELETE',
  'DROP',
  'ALTER',
  'CREATE',
  'TRUNCATE',
  'GRANT',
  'REVOKE',
  'EXEC',
  'EXECUTE',
];

/**
 * Validates that a SQL query is a single read-only SELECT statement.
 */
export function validateSelectQuery(sql: string): {
  valid: boolean;
  error?: string;
} {
  const trimmed = sql.trim();
  if (!trimmed) {
    return { valid: false, error: 'Query cannot be empty' };
  }

  // Strip SQL comments (-- line comments and /* block comments */)
  const withoutComments = trimmed
    .replace(/--[^\n]*/g, '')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .trim();

  if (!withoutComments) {
    return { valid: false, error: 'Query cannot be empty after removing comments' };
  }

  // Check the first meaningful token is SELECT or WITH (for CTEs)
  const firstToken = withoutComments.split(/\s+/)[0].toUpperCase();
  if (firstToken !== 'SELECT' && firstToken !== 'WITH') {
    return {
      valid: false,
      error: 'Only SELECT queries are allowed',
    };
  }

  // Check for forbidden keywords as standalone tokens
  const upperSql = withoutComments.toUpperCase();
  for (const keyword of FORBIDDEN_KEYWORDS) {
    // Match keyword as a whole word (not part of column/table names)
    const regex = new RegExp(`\\b${keyword}\\b`, 'i');
    if (regex.test(upperSql)) {
      return {
        valid: false,
        error: `Forbidden keyword: ${keyword}`,
      };
    }
  }

  // Check for multiple statements (semicolons followed by non-whitespace)
  const withoutStrings = withoutComments.replace(/'[^']*'/g, '');
  const statements = withoutStrings.split(';').filter((s) => s.trim().length > 0);
  if (statements.length > 1) {
    return {
      valid: false,
      error: 'Multiple statements are not allowed',
    };
  }

  return { valid: true };
}

/**
 * Single source of truth for the keyboard shortcuts shipped by the
 * sheets editor. The runtime bindings live in `worksheet.ts` (keyRules
 * via `runKeyRules`); this catalog drives the help modal opened by
 * Cmd/Ctrl+/.
 *
 * Keys use platform-neutral tokens:
 *   - `Mod`  — Cmd on macOS, Ctrl elsewhere
 *   - `Shift`, `Alt`
 *   - Named keys (`Enter`, `Tab`, `Esc`, `Arrow ↑`, …)
 *   - Printable letters in upper case (`A`, `B`, …)
 *
 * A combo is a `+`-joined string; alternative combos are an array.
 */

export type ShortcutCategory =
  | 'Navigation'
  | 'Selection'
  | 'Editing'
  | 'Clipboard'
  | 'Format'
  | 'Find'
  | 'Comments'
  | 'History'
  | 'Help';

export interface ShortcutEntry {
  category: ShortcutCategory;
  keys: ReadonlyArray<string>;
  description: string;
}

export const SHORTCUTS: ReadonlyArray<ShortcutEntry> = [
