/**
 * Renders the SheetView component.
 */
export function SheetView({
  tabId,
  readOnly = false,
  peerJumpTarget = null,
  commentJumpTarget = null,
  addPivotTab,
  workspaceId,
  onToggleCommentsPanel,
}: {
  tabId: string;
  readOnly?: boolean;
  peerJumpTarget?: {
    activeCell: NonNullable<UserPresence["activeCell"]>;
    targetTabId?: UserPresence["activeTabId"];
    requestId: number;
  } | null;
  commentJumpTarget?: {
    sref: string;
    requestId: number;
  } | null;
  addPivotTab?: (sourceTabId: string, sourceRange: string) => void;
  workspaceId?: string;
  onToggleCommentsPanel?: () => void;
}) {
  const { resolvedTheme: theme } = useTheme();
  const containerRef = useRef<HTMLDivElement>(null);
  const [didMount, setDidMount] = useState(false);
  const [sheetRenderVersion, setSheetRenderVersion] = useState(0);
  const [selectedChartId, setSelectedChartId] = useState<string | null>(null);
  const [selectedImageId, setSelectedImageId] = useState<string | null>(null);
  const [chartEditorOpen, setChartEditorOpen] = useState(false);
  const [conditionalFormatOpen, setConditionalFormatOpen] = useState(false);

  // Comment popover state. The pinned axis-ID anchor is what makes the popover
  // resilient to remote renders: notifySelectionChange fires on every render
  // (including remote-change repaints), so comparing axis IDs lets us tell
  // "user moved to a new cell" apart from "remote tick on the same cell".
  const [commentPopoverOpen, setCommentPopoverOpen] = useState(false);
  const [activeCellForComment, setActiveCellForComment] = useState<Ref | null>(null);
  const commentPopoverOpenRef = useRef(false);
  const popoverAnchorRef = useRef<{ rowId: string; colId: string } | null>(null);
  const { data: currentUserData } = useQuery({
    queryKey: ["me", "optional"],
    queryFn: fetchMeOptional,
    retry: false,
    staleTime: 5 * 60 * 1000,
  });
  const commentAuthor = useMemo<CommentAuthor | null>(
    () =>
      currentUserData
        ? {
            userId: String(currentUserData.id),
            username: currentUserData.username,
            photo: currentUserData.photo || undefined,
          }
        : null,
    [currentUserData],
  );
  const mentionMembers = useWorkspaceMembers(workspaceId);
  const [paintFormatActive, setPaintFormatActive] = useState(false);
  const [paintFormatSourceRef, setPaintFormatSourceRef] = useState<Ref | null>(
    null,
  );
  const [paintFormatSourceIndicatorVisible, setPaintFormatSourceIndicatorVisible] =
    useState(false);
  const [findBarOpen, setFindBarOpen] = useState(false);
  const [shortcutsHelpOpen, setShortcutsHelpOpen] = useState(false);
  const isMobile = useIsMobile();
  const [mobileEditState, setMobileEditState] = useState<{
    cellRef: string;
    value: string;
  } | null>(null);
  const mobileEditValueRef = useRef<string>("");
  const mobileEditOpenedAtRef = useRef<number>(0);
  const isMobileRef = useRef(isMobile);
  useEffect(() => {
    isMobileRef.current = isMobile;
  }, [isMobile]);
  const lastHandledPeerJumpRequestIdRef = useRef(0);
  const lastHandledCommentJumpRequestIdRef = useRef(0);
  const sheetRef = useRef<Spreadsheet | undefined>(undefined);
  const hasChartsRef = useRef(false);
  const hasImagesRef = useRef(false);
  const paintFormatActiveRef = useRef(false);
  const paintFormatPointerDownRef = useRef(false);
  const paintFormatApplyPendingRef = useRef(false);
  const paintFormatApplyingRef = useRef(false);
  const paintFormatUseDefaultStyleRef = useRef(false);
  const paintFormatSourceIndicatorVisibleRef = useRef(false);
  const paintFormatStyleRef = useRef<Partial<CellStyle> | undefined>(undefined);
  const storeRef = useRef<YorkieStore | undefined>(undefined);
  const { doc, loading, error } = useDocument<
    SpreadsheetDocument,
    UserPresence
  >();
  useMobileSheetGestures({ containerRef, sheetRef });

  const [pivotEditorOpen, setPivotEditorOpen] = useState(false);
  const root = doc?.getRoot();
  const hasCharts = !!root && Object.keys(root.sheets[tabId]?.charts || {}).length > 0;
  const hasImages = !!root && Object.keys(root.sheets[tabId]?.images || {}).length > 0;
  const selectedChart =
    root && selectedChartId ? root.sheets[tabId]?.charts?.[selectedChartId] : undefined;

  // Detect whether the active tab is a pivot sheet via TabMeta.kind
  // (avoids reading deeply nested pivotTable from Yorkie CRDT proxy)
  const isPivotTab = root?.tabs[tabId]?.kind === "pivot";

  // Derive the comment anchor (stable rowId/colId) for the active cell
  const activeCellCommentAnchor = useMemo((): CommentAnchor | null => {
    if (!root || !activeCellForComment) return null;
    const ws = root.sheets[tabId];
    if (!ws) return null;
    const rowId = ws.rowOrder?.[activeCellForComment.r - 1];
    const colId = ws.colOrder?.[activeCellForComment.c - 1];
    if (!rowId || !colId) return null;
    return { kind: 'sheet-cell', tabId, rowId, colId };
  }, [root, tabId, activeCellForComment]);

  // Open threads for the active cell (unresolved only). Detach via copyThread
  // so React consumers see plain numbers for createdAt / editedAt instead of
  // the bigint values Yorkie returns from its Long primitives (see Issue B).
  const activeCellThreads = useMemo((): Thread[] => {
    if (!root || !activeCellCommentAnchor) return [];
    const ws = root.sheets[tabId];
    if (!ws?.comments) return [];
    return Object.values(ws.comments as Record<string, Thread>)
      .filter(
        (t) =>
          !t.resolved &&
          t.anchor.rowId === activeCellCommentAnchor.rowId &&
          t.anchor.colId === activeCellCommentAnchor.colId,
      )
      .map((t) => copyThread(t as Thread));
  }, [root, tabId, activeCellCommentAnchor]);

  useEffect(() => {
    // Auto-open pivot editor when switching to a pivot tab
    if (isPivotTab) {
      setPivotEditorOpen(true);
    } else {
      setPivotEditorOpen(false);
    }
  }, [isPivotTab, tabId]);

  useEffect(() => {
    hasChartsRef.current = hasCharts;
  }, [hasCharts]);

  useEffect(() => {
    hasImagesRef.current = hasImages;
  }, [hasImages]);

  const clearPaintFormatState = useCallback(() => {
    paintFormatActiveRef.current = false;
    paintFormatPointerDownRef.current = false;
    paintFormatApplyPendingRef.current = false;
    paintFormatApplyingRef.current = false;
    paintFormatUseDefaultStyleRef.current = false;
