      // above just seeded any missing IDs, so they are guaranteed to resolve.
      const ws = doc?.getRoot().sheets[tabId];
      const rowId = ws?.rowOrder?.[activeCell.r - 1];
      const colId = ws?.colOrder?.[activeCell.c - 1];
