    let sheet: Awaited<ReturnType<typeof initialize>> | undefined;
    const unsubs: Array<() => void> = [];
    let cancelled = false;
    let recalcInFlight = false;
    let recalcPending = false;
    let selectionFrame: number | null = null;
    let overlayFrame: number | null = null;
    let recalcFrame: number | null = null;

    const store = new YorkieStore(doc, tabId);
    storeRef.current = store;
    initialize(container, {
      theme,
      store,
      readOnly,
      hideFormulaBar: isMobileRef.current,
      hideAutofillHandle: isMobileRef.current,
      showMobileHandles: isMobileRef.current,
    }).then((s) => {
      if (cancelled) {
        s.cleanup();
        return;
      }

      sheet = s;
      sheetRef.current = s;
      setSheetRenderVersion((v) => v + 1);

      if (isMobileRef.current && !readOnly) {
        s.setMobileEditCallback((cellRef, value) => {
          mobileEditValueRef.current = value;
          mobileEditOpenedAtRef.current = Date.now();
          setMobileEditState({ cellRef, value });
        });
      }

      // Track sheet render cycles (scroll/selection/edits) so floating chart
      // objects stay aligned with the canvas viewport.
      unsubs.push(
        s.onSelectionChange(() => {
          if (
            (hasChartsRef.current || hasImagesRef.current || paintFormatSourceIndicatorVisibleRef.current || isMobileRef.current) &&
            selectionFrame === null
          ) {
            selectionFrame = requestAnimationFrame(() => {
              selectionFrame = null;
              setSheetRenderVersion((v) => v + 1);
            });
          }

          if (
            !paintFormatActiveRef.current ||
            !paintFormatApplyPendingRef.current ||
            paintFormatApplyingRef.current
          ) {
            return;
          }

          paintFormatApplyPendingRef.current = false;
          if (s.getSelectionType() !== "cell") {
            return;
          }

          paintFormatApplyingRef.current = true;
          const styleToApply = paintFormatStyleRef.current;
          const applyPromise = paintFormatUseDefaultStyleRef.current
            ? s.applyDefaultStyle()
            : styleToApply
              ? s.applyStyle(styleToApply)
              : s.applyDefaultStyle();
          void applyPromise.finally(() => {
            clearPaintFormatState();
          });
        }),
      );

      unsubs.push(
        s.onSelectionChange(() => {
          setMobileEditState((prev) => {
            if (!prev) return null;
            // Guard against synthesized mouse events that iOS browsers
            // fire after touchend despite preventDefault().  These cause
            // a selectStart → selectionChange that would immediately
            // dismiss the mobile edit panel after a double-tap opens it.
            if (Date.now() - mobileEditOpenedAtRef.current < 500) {
              return prev;
            }
            const currentValue = mobileEditValueRef.current;
            if (currentValue !== prev.value) {
              void sheetRef.current?.commitExternalEdit(currentValue);
            }
            return null;
          });
        }),
      );

      // Track active cell for comment popover; auto-open when cell has comments.
      // notifySelectionChange fires on every render (worksheet.setOnRender),
      // so this runs on remote-change repaints too. We compare axis IDs
      // against the popover's pinned anchor to distinguish a real selection
      // move from a render tick on the same logical cell — otherwise typing
      // in the composer would be force-cancelled by any remote change.
      unsubs.push(
        s.onSelectionChange(() => {
          const activeCell = s.getActiveCell();
          if (!activeCell) return;
          setActiveCellForComment({ ...activeCell });

          const wsNow = doc.getRoot().sheets[tabId];
          if (!wsNow) return;
          const rowId = wsNow.rowOrder?.[activeCell.r - 1];
          const colId = wsNow.colOrder?.[activeCell.c - 1];

          if (commentPopoverOpenRef.current) {
            const pinned = popoverAnchorRef.current;
            // Same logical cell (axis IDs unchanged) → keep popover open even
            // if {r,c} shifted because of a remote row/col insert/delete.
            if (
              pinned &&
              rowId === pinned.rowId &&
              colId === pinned.colId
            ) {
              return;
            }
            // Either user moved to a different cell, or the pinned row/col
            // was deleted remotely — close the popover.
            setCommentPopoverOpen(false);
            return;
          }

          // Popover is closed — auto-open if the new cell has unresolved threads.
          if (!rowId || !colId) return;
          if (!wsNow.comments) return;
          const hasThreads = Object.values(
            wsNow.comments as Record<string, Thread>,
          ).some(
            (t) =>
              !t.resolved &&
              t.anchor.rowId === rowId &&
              t.anchor.colId === colId,
          );
          if (hasThreads) {
            popoverAnchorRef.current = { rowId, colId };
            setCommentPopoverOpen(true);
          }
        }),
      );

      const runRemoteSync = (needsRecalc: boolean) => {
        if (cancelled || !sheet) return;
        if (recalcInFlight) {
          recalcPending = true;
          return;
        }

        recalcInFlight = true;
        sheet
          .reloadDimensions()
          .then(() => {
            if (cancelled || !sheet) return;
            if (needsRecalc) {
              return sheet.recalculateCrossSheetFormulas();
            }
            sheet.render();
          })
          .finally(() => {
            recalcInFlight = false;
            if (recalcPending) {
              recalcPending = false;
              queueMicrotask(() => runRemoteSync(needsRecalc));
            }
          });
      };

      const scheduleRemoteSync = (needsRecalc: boolean) => {
        if (cancelled || recalcFrame !== null) return;
        recalcFrame = requestAnimationFrame(() => {
          recalcFrame = null;
          runRemoteSync(needsRecalc);
        });
      };

      const scheduleOverlayRender = () => {
        if (overlayFrame !== null) return;
        overlayFrame = requestAnimationFrame(() => {
          overlayFrame = null;
          if (!cancelled && sheet) {
            sheet.renderOverlay();
          }
        });
      };

      // Wire up cross-sheet formula resolver
      s.setGridResolver(
        (sheetName: string, refs: Set<Sref>): Grid | undefined => {
          const root = doc.getRoot();
          // Find a worksheet tab by name (case-insensitive).
          const targetTabId = root.tabOrder.find((candidateTabId: string) => {
            const tab = root.tabs[candidateTabId];
            return (
              tab?.type === "sheet" &&
              tab.name.toUpperCase() === sheetName
            );
          });
          if (!targetTabId) return undefined;

          const ws = root.sheets[targetTabId];
          if (!ws) return undefined;

          const coverToAnchor = new Map<Sref, Sref>();
          if (ws.merges) {
            for (const [anchorSref, span] of Object.entries(ws.merges)) {
              const anchorRef = parseRef(anchorSref);
              for (let r = anchorRef.r; r < anchorRef.r + span.rs; r++) {
                for (let c = anchorRef.c; c < anchorRef.c + span.cs; c++) {
                  const covered = toSref({ r, c });
                  if (covered === anchorSref) continue;
                  coverToAnchor.set(covered, anchorSref);
                }
              }
            }
          }

          const grid: Grid = new Map();
          for (const localRef of refs) {
            const ref = parseRef(localRef);
            const sref = toSref(ref);
            const anchorSref = coverToAnchor.get(sref) || sref;
            const cellData = getWorksheetCell(ws, parseRef(anchorSref));
            if (cellData) {
              grid.set(localRef, cellData as Cell);
            }
          }
          return grid;
        },
      );

      // Wire up FormulaResolver for cross-sheet cycle detection
      const currentTabName = doc.getRoot().tabs[tabId]?.name ?? '';
      s.setFormulaResolver(
        (sheetName: string): Map<string, string> | undefined => {
          const root = doc.getRoot();
          const targetTabId = root.tabOrder.find((candidateTabId: string) => {
            const tab = root.tabs[candidateTabId];
            return (
              tab?.type === "sheet" &&
              tab.name.toUpperCase() === sheetName
            );
          });
          if (!targetTabId) return undefined;

          const ws = root.sheets[targetTabId];
          if (!ws?.cells) return undefined;

          const formulas = new Map<string, string>();
          for (const [rowStr, cols] of Object.entries(ws.cells)) {
            if (!cols || typeof cols !== 'object') continue;
            for (const [colStr, cellData] of Object.entries(
              cols as Record<string, unknown>,
            )) {
              const cell = cellData as { f?: string } | undefined;
              if (cell?.f) {
                const r = parseInt(rowStr, 10);
                const c = parseInt(colStr, 10);
                formulas.set(toSref({ r, c }), cell.f);
              }
            }
          }
          return formulas;
        },
        currentTabName,
      );

      // Recalculate cross-sheet formulas on initial load (tab switch)
      // so that any changes made in other sheets are reflected immediately.
      runRemoteSync(true);

      // Re-render on any remote change. Cell/merge/tab-name changes also
      // trigger cross-sheet formula recalculation; all other changes
      // (styles, dimensions, charts, filters, etc.) only reload state and
      // re-render without the expensive recalc pass.
      unsubs.push(
        doc.subscribe((e) => {
          if (e.type !== "remote-change") return;
          const ops = (
            e as { value?: { operations?: Array<{ path?: string }> } }
          ).value?.operations;
          scheduleRemoteSync(needsRecalc(ops));
        }),
      );
      unsubs.push(doc.subscribe("presence", scheduleOverlayRender));
    });

    return () => {
      cancelled = true;
      if (sheet) {
        sheet.cleanup();
      }
      sheetRef.current = undefined;
      storeRef.current = undefined;
      if (selectionFrame !== null) {
        cancelAnimationFrame(selectionFrame);
      }
      if (overlayFrame !== null) {
        cancelAnimationFrame(overlayFrame);
      }
      if (recalcFrame !== null) {
        cancelAnimationFrame(recalcFrame);
      }

      for (const unsub of unsubs) {
        unsub();
      }
    };
  }, [clearPaintFormatState, didMount, containerRef, doc, tabId, readOnly, theme]);

  useEffect(() => {
    if (!selectedChartId) return;
    if (!root?.sheets[tabId]?.charts?.[selectedChartId]) {
      setSelectedChartId(null);
      setChartEditorOpen(false);
    }
  }, [root, selectedChartId, tabId]);

  useEffect(() => {
    if (!selectedImageId) return;
    if (!root?.sheets[tabId]?.images?.[selectedImageId]) {
      setSelectedImageId(null);
    }
  }, [root, selectedImageId, tabId]);

  useEffect(() => {
    if (!peerJumpTarget) return;
    if (peerJumpTarget.targetTabId && peerJumpTarget.targetTabId !== tabId) {
      return;
    }
    if (peerJumpTarget.requestId === lastHandledPeerJumpRequestIdRef.current) {
      return;
    }

    const sheet = sheetRef.current;
    if (!sheet) return;

    lastHandledPeerJumpRequestIdRef.current = peerJumpTarget.requestId;
    setSelectedChartId(null);
    setChartEditorOpen(false);
    setConditionalFormatOpen(false);

    try {
      void sheet.focusCell(parseRef(peerJumpTarget.activeCell));
    } catch {
      // Ignore malformed presence values from remote peers.
    }
  }, [peerJumpTarget, sheetRenderVersion, tabId]);

  useEffect(() => {
    if (!commentJumpTarget) return;
    if (commentJumpTarget.requestId === lastHandledCommentJumpRequestIdRef.current) {
      return;
    }

    const sheet = sheetRef.current;
    if (!sheet) return;

    lastHandledCommentJumpRequestIdRef.current = commentJumpTarget.requestId;
    setSelectedChartId(null);
    setChartEditorOpen(false);
    setConditionalFormatOpen(false);

    try {
      void sheet.focusCell(parseRef(commentJumpTarget.sref));
    } catch {
      // Ignore malformed sref values.
    }
  }, [commentJumpTarget, sheetRenderVersion]);

  const paintFormatSourceIndicator = (() => {
    if (!paintFormatSourceIndicatorVisible || !paintFormatSourceRef) {
      return null;
    }
    const sheet = sheetRef.current;
    if (!sheet) return null;

    try {
      const viewport = sheet.getGridViewportRect();
      const sourceRect = sheet.getCellRect(paintFormatSourceRef);
      return (
        <div
          className="absolute pointer-events-none rounded-[2px]"
          style={{
            left: viewport.left + sourceRect.left,
            top: viewport.top + sourceRect.top,
            width: sourceRect.width,
            height: sourceRect.height,
            boxShadow: "inset 0 0 0 2px var(--color-primary)",
            zIndex: 12,
          }}
        />
      );
    } catch {
      return null;
    }
  })();

  // Comment popover placement — see docs/design/sheets/comments.md §6.5.
  // Preference order: right of cell → left of cell → stacked below/above.
  // Side modes keep the popover top-aligned with the cell, flipping up if
  // the bottom would overflow. Stacked mode clamps horizontally. In every
  // mode the active cell stays uncovered.
  const commentPopoverWrapperRef = useRef<HTMLDivElement>(null);
  const [commentPopoverPos, setCommentPopoverPos] = useState<{
    left: number;
    top: number;
  } | null>(null);

  // Reset position whenever the popover closes so the next open re-measures
  // before paint (avoids flashing at the previous cell's coords).
  useEffect(() => {
    if (!commentPopoverOpen) setCommentPopoverPos(null);
  }, [commentPopoverOpen]);

  useLayoutEffect(() => {
    if (!commentPopoverOpen || !activeCellForComment) return;
    const wrapper = commentPopoverWrapperRef.current;
    const sheet = sheetRef.current;
    if (!wrapper || !sheet) return;
    const parent = wrapper.parentElement;
    if (!parent) return;

    let cellRect;
    let viewport;
    try {
      viewport = sheet.getGridViewportRect();
      cellRect = sheet.getCellRect(activeCellForComment);
    } catch {
      return;
    }

    const popoverRect = wrapper.getBoundingClientRect();
    const parentRect = parent.getBoundingClientRect();
    const popoverW = popoverRect.width;
    const popoverH = popoverRect.height;
    // Bail out if the wrapper hasn't rendered its child yet (first paint
    // before CommentPopover mounts); we'll re-run once it has dimensions.
    if (popoverW === 0 || popoverH === 0) return;

    const GAP = 4;
    const PAD = 8;
    const parentW = parentRect.width;
    const parentH = parentRect.height;

    const cellLeft = viewport.left + cellRect.left;
    const cellTop = viewport.top + cellRect.top;
    const cellRight = cellLeft + cellRect.width;
    const cellBottom = cellTop + cellRect.height;

    const fitsRight = cellRight + GAP + popoverW <= parentW - PAD;
    const fitsLeft = cellLeft - GAP - popoverW >= PAD;

    let left: number;
    let stacked = false;
    if (fitsRight) {
      left = cellRight + GAP;
    } else if (fitsLeft) {
      left = cellLeft - GAP - popoverW;
    } else {
      stacked = true;
      left = Math.max(PAD, Math.min(parentW - PAD - popoverW, cellLeft));
    }

    let top: number;
    if (!stacked) {
      // Top-aligned with cell, flip up if bottom overflows.
      if (cellTop + popoverH <= parentH - PAD) {
        top = Math.max(PAD, cellTop);
      } else {
        top = Math.max(PAD, cellBottom - popoverH);
      }
    } else if (cellBottom + GAP + popoverH <= parentH - PAD) {
      top = cellBottom + GAP;
    } else if (cellTop - GAP - popoverH >= PAD) {
      top = cellTop - GAP - popoverH;
    } else {
      top = Math.max(PAD, parentH - PAD - popoverH);
    }

    setCommentPopoverPos((prev) =>
      prev && prev.left === left && prev.top === top ? prev : { left, top },
    );
  }, [
    commentPopoverOpen,
    activeCellForComment,
    activeCellThreads.length,
    sheetRenderVersion,
  ]);

  if (loading) {
    return <Loader />;
  }

  if (error) {
    return (
      <div className="flex h-full w-full items-center justify-center">
        <div className="text-red-500">{error.message}</div>
      </div>
    );
  }

  return (
    <div className="flex h-full w-full flex-col">
      {!readOnly && (
        <FormattingToolbar
          spreadsheet={sheetRef.current}
          isPivotTab={isPivotTab}
          onInsertChart={handleInsertChart}
          onInsertImage={handleInsertImage}
          onOpenConditionalFormat={handleOpenConditionalFormat}
          onTogglePaintFormat={() => {
            void handleTogglePaintFormat();
          }}
          paintFormatActive={paintFormatActive}
        />
      )}
      <div className="relative flex-1 w-full">
        <SheetContextMenu
          spreadsheet={sheetRef.current}
          readOnly={readOnly}
          onCopy={handleContextMenuCopy}
          onCut={handleContextMenuCut}
          onPaste={handleContextMenuPaste}
          onDeleteCellData={handleContextMenuDelete}
          onInsertBefore={handleInsertBefore}
          onInsertAfter={handleInsertAfter}
          onDeleteRowCol={handleDeleteRowCol}
          onInsertPivotTable={addPivotTab ? handleInsertPivotTable : undefined}
          selectedImageId={selectedImageId}
          onDeleteImage={() => {
            if (selectedImageId) {
              handleDeleteImage(selectedImageId);
            }
          }}
          onInsertComment={readOnly ? undefined : openCommentComposerForActiveCell}
        >
          <div className="relative h-full w-full">
            <div
              ref={containerRef}
              className="h-full w-full select-none"
              data-sheet-container
              style={{ touchAction: "manipulation", WebkitTouchCallout: "none" }}
              onPointerDown={handleGridPointerDown}
              onDragOver={handleDragOver}
              onDrop={handleDrop}
            />
            {root && hasImages && (
              <Suspense fallback={null}>
                <ImageObjectLayer
                  spreadsheet={sheetRef.current}
                  root={root}
                  tabId={tabId}
                  readOnly={readOnly}
                  selectedImageId={selectedImageId}
                  onSelectImage={handleSelectImage}
                  onUpdateImage={handleUpdateImage}
                  onDeleteImage={handleDeleteImage}
                  renderVersion={sheetRenderVersion}
                />
              </Suspense>
            )}
          </div>
        </SheetContextMenu>
        {findBarOpen && (
          <FindBar
            spreadsheet={sheetRef.current}
            onClose={handleFindBarClose}
          />
        )}
        <SheetsShortcutsHelp
          open={shortcutsHelpOpen}
          onOpenChange={setShortcutsHelpOpen}
        />
        {paintFormatSourceIndicator}
        {root && hasCharts && (
          <Suspense fallback={null}>
            <ChartObjectLayer
              spreadsheet={sheetRef.current}
              root={root}
              tabId={tabId}
              readOnly={readOnly}
              selectedChartId={selectedChartId}
              onSelectChart={handleSelectChart}
              onRequestEditChart={handleEditChart}
              onDeleteChart={handleDeleteChart}
              onUpdateChart={handleUpdateChart}
              renderVersion={sheetRenderVersion}
            />
          </Suspense>
        )}
        {root && !readOnly && chartEditorOpen && (
          <Suspense fallback={null}>
            <ChartEditorPanel
              root={root}
              chart={selectedChart}
              open={chartEditorOpen}
              onClose={() => setChartEditorOpen(false)}
              onUpdateChart={handleUpdateChart}
              getSelectionRange={getSelectionRange}
            />
          </Suspense>
        )}
        {!readOnly && conditionalFormatOpen && (
          <Suspense fallback={null}>
            <ConditionalFormatPanel
              spreadsheet={sheetRef.current}
              open={conditionalFormatOpen}
              onClose={() => setConditionalFormatOpen(false)}
              getSelectionRange={getSelectionRange}
            />
          </Suspense>
        )}
        {!readOnly && isPivotTab && !pivotEditorOpen && (
          <button
            type="button"
            className="absolute right-4 top-4 z-10 flex items-center gap-1.5 rounded-md border bg-background px-3 py-1.5 text-xs font-medium shadow-sm hover:bg-muted"
            onClick={() => setPivotEditorOpen(true)}
          >
            Edit pivot table
          </button>
        )}
        {!readOnly && doc && isPivotTab && pivotEditorOpen && (
          <Suspense fallback={null}>
            <PivotEditorPanel
              doc={doc}
              tabId={tabId}
              onClose={() => setPivotEditorOpen(false)}
              onRefresh={() => {
                const sheet = sheetRef.current;
                if (sheet) {
                  sheet.invalidateStore();
                  sheet.reloadDimensions().then(() => {
                    sheet.render();
                    setSheetRenderVersion((v) => v + 1);
                  });
                }
              }}
            />
          </Suspense>
        )}
        {isMobile && mobileEditState && (
          <MobileEditPanel
            cellRef={mobileEditState.cellRef}
            initialValue={mobileEditState.value}
            onCommit={handleMobileEditCommit}
            onCancel={handleMobileEditCancel}
            onValueChange={handleMobileEditValueChange}
          />
        )}
        {commentPopoverOpen && activeCellForComment && (
          <div
            ref={commentPopoverWrapperRef}
            className="absolute z-30"
            style={{
              left: commentPopoverPos?.left ?? 0,
              top: commentPopoverPos?.top ?? 0,
              visibility: commentPopoverPos ? "visible" : "hidden",
            }}
          >
            <CommentPopover
              threads={activeCellThreads}
              currentUser={commentAuthor}
              members={mentionMembers}
              onAddThread={handleCommentAddThread}
              onReply={handleCommentReply}
              onResolve={handleCommentResolve}
              onEditComment={handleCommentEdit}
              onDeleteComment={handleCommentDelete}
              onClose={() => setCommentPopoverOpen(false)}
            />
          </div>
        )}
      </div>
    </div>
  );
}

export default SheetView;
